def build_url(base, *parts, **query):
    url = base.rstrip("/")
    for part in parts:
        url += "/" + str(part).strip("/")
    params = []
    for key, value in query.items():
        if value is None:
            continue
        if isinstance(value, bool):
            value = "true" if value else "false"
        params.append(f"{key}={value}")
    if params:
        url += "?" + "&".join(params)
    return url


