    def __init__(self, owner):
        self.owner = owner
        self._points = 0
        self._earned_total = 0

    @property
    def points(self):
        return self._points

    @property
    def level(self):
        if self._earned_total >= 5000:
            return "gold"
        if self._earned_total >= 1000:
            return "silver"
        return "bronze"

    def earn(self, purchase_sum):
        if purchase_sum <= 0:
            return 0
        earned = purchase_sum * self.PERCENT // 100
        self._points += earned
        self._earned_total += earned
        return earned

    def spend(self, amount):
        if amount <= 0 or amount > self._points:
            return False
        self._points -= amount
        return True


