class CoffeeError(Exception):
    pass


class UnknownDrink(CoffeeError):
    pass


class OutOfStock(CoffeeError):
    pass


class NotEnoughBalance(CoffeeError):
    def __init__(self, missing):
        super().__init__(f"не хватает {missing} ₽")
        self.missing = missing


def make_order(drink, balance, stock):
    if drink not in PRICES:
        raise UnknownDrink(f"неизвестный напиток {drink}")
    if stock.get(drink, 0) == 0:
        raise OutOfStock(drink)
    price = PRICES[drink]
    if balance < price:
        raise NotEnoughBalance(price - balance)
    stock[drink] -= 1
    return balance - price


def handle(drink, balance, stock):
    try:
        left = make_order(drink, balance, stock)
    except OutOfStock as e:
        return f"Нет в наличии: {e}"
    except NotEnoughBalance as e:
        return f"Не хватает {e.missing} ₽"
    except CoffeeError as e:
        return f"Ошибка заказа: {e}"
    return f"Готово, на балансе {left} ₽"

