class Pool:
    def __init__(self, size):
        self.free = size

    def acquire(self):
        if self.free == 0:
            raise RuntimeError("пул соединений исчерпан")
        self.free -= 1
        return "conn"

    def release(self, conn):
        self.free += 1


def reserve(conn, order):
    # в жизни здесь запрос к базе через conn
    available = STOCK[order["sku"]]
    if order["qty"] > available:
        raise ValueError(f"на складе только {available} шт.")
    return f"reserved {order['qty']} x {order['sku']}"


def save_order(pool, order):
    conn = pool.acquire()
    try:
        result = reserve(conn, order)
    except ValueError as e:
        return f"rejected: {e}"
    pool.release(conn)
    return result


def run(pool_size, orders):
    pool = Pool(pool_size)
    results = []
    for order in orders:
        try:
            results.append(save_order(pool, order))
        except KeyError:
            results.append("error: неизвестный товар")
        except RuntimeError as e:
            results.append(f"error: {e}")
    results.append(pool.free)
    return results

