def matches(value, lookup, arg):
    if lookup == "isnull":
        return (value is None) == arg
    if lookup == "exact":
        return value == arg
    if value is None:
        return False
    if lookup == "lt":
        return value < arg
    if lookup == "lte":
        return value <= arg
    if lookup == "gt":
        return value > arg
    if lookup == "gte":
        return value >= arg
    if lookup == "icontains":
        return arg.lower() in value.lower()
    if lookup == "in":
        return value in arg
    raise ValueError(f"unknown lookup: {lookup}")


def filter_rows(rows, filters):
    result = []
    for row in rows:
        ok = True
        for key, arg in filters.items():
            field, _, lookup = key.partition("__")
            if not lookup:
                lookup = "exact"
            if not matches(row.get(field), lookup, arg):
                ok = False
                break
        if ok:
            result.append(row["id"])
    return sorted(result)

